import json
with open('/home/ubuntu/.agent-ml-research-prod_0510/projects/causal_annot_error_attrib/artifacts/plan006/asv_empirical_results.json') as f:
    d = json.load(f)

asvs = d.get('asvs', [])
# Get K=10 magnitude ASVs, grouped by topology (excluding qwen3_few-shot-5)
from collections import defaultdict
topo_asvs = defaultdict(list)
for x in asvs:
    if x.get('asv_type')=='magnitude' and x.get('K')==10:
        if not (x['model']=='qwen3' and x['prompt']=='few-shot-5'):
            if x.get('asv') is not None:
                topo_asvs[x['topology']].append(x['asv'])

print('HumAID K=10 ASV ranges per topology (paper claims):')
for topo in ['iv', 'mediation', 'frontdoor', 'exposure', 'confounding', 'collider', 'mbias']:
    vals = topo_asvs.get(topo, [])
    if vals:
        print(f'  {topo:15s}: {len(vals)} configs, ASV = {min(vals):.2f}--{max(vals):.2f}')
    else:
        print(f'  {topo:15s}: no non-null ASVs (safe)')
" 2>&1

